        var mockPatient = new Mock<Patient>();
        var mockAppointment = new Mock<Appointment>();

        // Act
        var patientAppointmentFile = new PatientAppointmentFile(mockPatient.Object, mockAppointment.Object);

        // Assert
        Assert.NotNull(patientAppointmentFile);
    }
}

public class WorkflowSystemTests
{
    [Fact]
    public void TestRoutingToDoctors()
    {
        // Arrange
        var mockPatient = new Mock<Patient>();
        var mockDoctor = new Mock<Doctor>();

        // Act
        var workflowSystem = new WorkflowSystem();
        workflowSystem.RouteToDoctors(mockPatient.Object, mockDoctor.Object);

        // Assert
        mockDoctor.Verify(d => d.ReceiveConsultationRequest(mockPatient.Object), Times.Once);
    }
}

public class WorkflowRoutingChemistAndLabsTests
{
